import {moments,newState,act,advance,reclaim} from './model.mjs';
const $=s=>document.querySelector(s);let state=newState(),live=false,viewer='you',demoVoice=0,pending=null,selected=null,audio=null;
try{const saved=JSON.parse(localStorage.getItem('streamlore-v1'));if(saved&&Number.isInteger(saved.chapter)&&saved.chapter>=0&&saved.chapter<6&&Array.isArray(saved.voters)&&Array.isArray(saved.unlocked)&&saved.claims&&saved.goal===3){state=saved;demoVoice=saved.voters.length;}}catch{}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function scene(m){const n=Number(m.chapter),c=m.color;const icons=[`<path d="M100 55L121 97L100 145L79 97Z" fill="${c}"/><circle cx="100" cy="98" r="10" fill="#202638"/><path d="M90 152L100 175L110 152" fill="${c}"/>`,`<path d="M25 118Q50 40 75 118T125 118T175 118M25 130Q50 208 75 130T125 130T175 130" fill="none" stroke="${c}" stroke-width="4"/><circle cx="100" cy="123" r="12" fill="${c}"/>`,`<circle cx="100" cy="116" r="45" fill="${c}"/><ellipse cx="100" cy="116" rx="78" ry="16" fill="none" stroke="#fff" stroke-width="4" transform="rotate(-30 100 116)"/><circle cx="86" cy="100" r="12" fill="#202638" opacity=".3"/>`,`<path d="M64 77Q125 45 143 104Q100 88 96 151Q51 142 64 77Z" fill="${c}"/><path d="M22 199V174H43V159H65V183H86V148H108V176H130V154H151V180H177V199Z" fill="#475466"/>`,`<path d="M100 42L112 88L153 65L132 110L176 124L131 139L148 185L111 159L100 204L87 159L48 181L67 139L24 124L69 109L49 66L87 88Z" fill="${c}"/><circle cx="100" cy="123" r="21" fill="#252c3e"/>`,`<path d="M47 119L100 72L153 119V176H47Z" fill="${c}"/><path d="M84 176V134H116V176" fill="#252c3e"/><path d="M29 123L100 60L171 123" fill="none" stroke="${c}" stroke-width="6"/>`][n-1];return `<svg viewBox="0 0 200 240" role="img" aria-label="Original animated illustration for ${esc(m.title)}"><defs><radialGradient id="g${n}"><stop stop-color="${c}" stop-opacity=".5"/><stop offset="1" stop-color="#171d2b"/></radialGradient></defs><rect width="200" height="240" fill="url(#g${n})"/><g fill="${c}">${[[20,28],[155,41],[178,180],[33,196],[85,36]].map(([x,y],i)=>`<circle cx="${x}" cy="${y+n*2}" r="${i%2+1}"/>`).join('')}</g><g class="scene-ring" fill="none" stroke="${c}" stroke-opacity=".55"><ellipse cx="100" cy="120" rx="83" ry="34" transform="rotate(${n*22} 100 120)"/><ellipse cx="100" cy="120" rx="70" ry="91" transform="rotate(${n*15} 100 120)"/></g><g class="scene-float">${icons}</g><text x="13" y="224" fill="${c}" font-size="8" font-family="monospace">NOVA / ORBIT ${m.chapter}</text><text x="145" y="224" fill="${c}" font-size="8" font-family="monospace">${m.rarity[0]}·01</text></svg>`;}
function card(m){return `<div class="lore-card" style="background:${m.color}"><div class="card-head"><span>STREAMLORE</span><span>✦ ${m.chapter}</span></div><div class="card-art">${scene(m)}</div><div class="card-info"><div class="card-title">${esc(m.title)}</div><div class="card-sub"><span>${m.rarity}</span><span>NOVA / S01</span></div></div></div>`;}
function save(){if(!live)try{localStorage.setItem('streamlore-v1',JSON.stringify(state));}catch{}}
function render(){const m=moments[state.chapter],unlocked=state.unlocked.includes(m.id),owned=state.claims[viewer]||[];$('#chapter').textContent=`${m.chapter} / 06`;$('#moment-title').textContent=m.title;$('#mini-card').innerHTML=card(m);$('#progress-text').textContent=`${Math.min(state.voters.length,3)} / 3 voices`;$('#bar').style.width=`${Math.min(100,state.voters.length/3*100)}%`;$('#progress-state').textContent=unlocked?'MOMENT UNLOCKED':'LET’S MAKE A MEMORY';$('#claim').disabled=!unlocked||owned.includes(m.id);$('#claim').textContent=owned.includes(m.id)?'In your collection ✓':unlocked?'Reveal your card ✦':'Moment not unlocked yet';$('#vote').disabled=live||unlocked;$('#vote').innerHTML=live?'Use !moment in Twitch chat':unlocked?'The community made it ✓':'Add a demo voice <span>↗</span>';$('#next').disabled=live||state.chapter===5;$('#count').textContent=owned.length;$('#archive').innerHTML=moments.map(x=>`<button class="card-wrap ${state.unlocked.includes(x.id)?'':'locked'}" data-card="${x.id}" aria-label="${esc(x.title)}: ${state.unlocked.includes(x.id)?'unlocked':'preview, not unlocked'}">${card(x)}<div class="card-caption"><span>CHAPTER ${x.chapter}</span><span>${owned.includes(x.id)?'COLLECTED ✓':state.unlocked.includes(x.id)?'AVAILABLE ↗':'PREVIEW ◌'}</span></div></button>`).join('');$('#album').innerHTML=moments.filter(x=>owned.includes(x.id)).map(x=>`<button class="card-wrap" data-card="${x.id}">${card(x)}</button>`).join('');$('#empty').hidden=owned.length>0;save();}
function log(user,text){const p=document.createElement('p'),b=document.createElement('b');b.textContent=user;p.append(b,document.createTextNode(text));$('#chat').append(p);while($('#chat').children.length>3)$('#chat').firstChild.remove();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function showCard(id){const m=moments.find(x=>x.id===id);if(!m)return;pending=m.id;const owns=(state.claims[viewer]||[]).includes(id),unlocked=state.unlocked.includes(id);$('#reveal-card').innerHTML=card(m);$('#reveal-title').textContent=m.title;$('#reveal-line').textContent=m.line;$('#keep').disabled=owns||!unlocked;$('#keep').textContent=owns?'Already in your collection ✓':!unlocked?'Preview only · chapter not unlocked':live?'Claim in Twitch chat: !claim '+m.chapter:'Keep this moment ↗';if(live)$('#keep').disabled=true;$('#reveal').showModal();}
$('#vote').onclick=()=>{const user='demo_viewer_'+(++demoVoice);state=act(state,{user,command:'!moment'});log(user,'!moment');render();if(state.unlocked.includes(moments[state.chapter].id))toast('A shared moment, unlocked. Reveal your card.');};
$('#claim').onclick=()=>showCard(moments[state.chapter].id);$('#keep').onclick=()=>{if(live)return;state=reclaim(state,viewer,pending);render();$('#reveal').close();toast('Saved to your demo album. No cash value.');};
$('#next').onclick=()=>{state=advance(state);render();log('orbitbot','A new chapter begins. Earlier moments stay available.');};
document.addEventListener('click',e=>{const b=e.target.closest('[data-card]');if(b)showCard(b.dataset.card);const v=e.target.closest('[data-view],[data-go]');if(v){const name=v.dataset.view||v.dataset.go;document.querySelectorAll('.view').forEach(x=>x.classList.toggle('hidden',x.id!==name));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===name));}});
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#reset').onclick=()=>{if(live){toast('Disconnect Twitch before resetting the demo.');return;}state=newState();demoVoice=0;render();toast('Demo album reset.');};
$('#connect').onclick=()=>{if(live){fetch('/api/disconnect',{method:'POST',headers:{'X-StreamLore':'1'}}).then(()=>location.reload());return;}$('#connection').showModal();};$('#oauth').hidden=true;
$('#sound').onclick=()=>{if(audio){audio.close();audio=null;$('#sound').textContent='♫';return;}const ctx=new AudioContext(),gain=ctx.createGain();gain.gain.value=.025;gain.connect(ctx.destination);[110,164.81,220].forEach(f=>{const osc=ctx.createOscillator();osc.frequency.value=f;osc.type='sine';osc.connect(gain);osc.start();});audio=ctx;$('#sound').textContent='Ⅱ';};
async function bridge(){if(!['localhost','127.0.0.1'].includes(location.hostname))return;try{const res=await fetch('/api/status');if(!res.ok)return;const s=await res.json();$('#oauth').hidden=!s.configured;$('#oauth').onclick=()=>location.assign('/auth/start');$('#conn-status').textContent=s.configured?'Registered app detected. Ready to authorize.':'Set TWITCH_CLIENT_ID before starting the bridge.';if(s.user){live=true;viewer=s.user.id;$('#mode').textContent=(s.connected?'TWITCH CONNECTED / ':'TWITCH CONNECTING / ')+s.user.login;$('#connect').textContent='Disconnect Twitch';$('#connection-info').textContent='Connected as '+s.user.login;const es=new EventSource('/api/events');es.addEventListener('state',e=>{const d=JSON.parse(e.data);state=d.state;render();});es.addEventListener('chat',e=>{const d=JSON.parse(e.data);log(d.login,d.text);});es.addEventListener('bridge',e=>{const message=JSON.parse(e.data).message;toast(message);if(message==='Twitch chat connected.')$('#mode').textContent='TWITCH CONNECTED / '+s.user.login;});}}catch{toast('Local bridge not available; using demo mode.');}}
render();bridge();
